BEGIN;
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT set_config('festapp.email_wake','scheduled',true);
DO $$
DECLARE org bigint; un bigint; oc bigint; ev bigint; grp bigint; hidden_user uuid:=gen_random_uuid(); viewer uuid:=gen_random_uuid();
 msg jsonb; oid bigint; visible_order bigint; result jsonb; kind text; legacy public.notification_center_events; delivery public.notification_center_deliveries;
BEGIN
 INSERT INTO public.organizations(title) VALUES('Hidden identity surfaces') RETURNING id INTO org;
 INSERT INTO public.units(organization,title) VALUES(org,'Privacy unit') RETURNING id INTO un;
 INSERT INTO auth.users(id) VALUES(hidden_user),(viewer);
 INSERT INTO public.user_info(id,organization,name,email_readonly) VALUES(hidden_user,org,'Hidden admin','hidden@test.invalid'),(viewer,org,'Visible editor','visible@test.invalid');
 INSERT INTO public.organization_users(organization,"user",is_admin,is_hidden) VALUES(org,hidden_user,true,true);
 INSERT INTO public.occasions(organization,unit,title,link,start_time,end_time) VALUES(org,un,'Privacy',gen_random_uuid()::text,now(),now()+interval '1 day') RETURNING id INTO oc;
 INSERT INTO public.occasion_users(occasion,"user",is_editor,is_editor_view,is_manager,is_editor_order_view) VALUES(oc,viewer,true,true,true,true),(oc,hidden_user,false,false,false,false);
 PERFORM public.initialize_notification_center_internal(org);
 msg:=public.enqueue_email('custom',jsonb_build_object('organization',org,'occasion',oc,'recipient_user',hidden_user),'hidden@test.invalid','{}','hidden-user');
 UPDATE public.email_messages SET bounced_at=clock_timestamp() WHERE message_id=(msg->>'message_id')::uuid;
 PERFORM public.notification_center_email_internal((msg->>'message_id')::uuid);
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org),0::bigint,'hidden email recipient generates no personal notification');
 msg:=public.enqueue_email('custom',jsonb_build_object('organization',org,'occasion',oc),' HIDDEN@test.invalid ','{}','hidden-email');
 UPDATE public.email_messages SET bounced_at=clock_timestamp() WHERE message_id=(msg->>'message_id')::uuid;
 PERFORM public.notification_center_email_internal((msg->>'message_id')::uuid);
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org),0::bigint,'email-only legacy identity is hidden with case and whitespace normalization');
 INSERT INTO eshop.orders(order_sequence,order_symbol,occasion,state,data) VALUES(public.next_order_sequence(oc),public.generate_order_symbol(),oc,'ordered','{"email":"hidden@test.invalid","name":"Hidden admin"}') RETURNING id INTO oid;
 FOREACH kind IN ARRAY ARRAY['order_created','waitlist_registered','order_cancelled','offer_accepted'] LOOP
  PERFORM public.notification_center_order_internal(oid,kind,'hidden',viewer);
 END LOOP;
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org),0::bigint,'all personal order and waitlist notifications hide hidden buyer');
 INSERT INTO eshop.orders(order_sequence,order_symbol,occasion,state,data) VALUES(public.next_order_sequence(oc),public.generate_order_symbol(),oc,'ordered','{"email":"customer@test.invalid","name":"Customer"}') RETURNING id INTO visible_order;
 PERFORM public.notification_center_order_internal(visible_order,'order_created','visible',hidden_user);
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org),1::bigint,'hidden operator does not hide actual customer business activity');
 INSERT INTO public.notification_center_events(organization,occasion,kind,source_key,data,occurred_at) VALUES(org,oc,'email_problem','hidden:legacy-email',jsonb_build_object('messageId',msg->>'message_id'),now()) RETURNING * INTO legacy;
 PERFORM set_config('request.jwt.claim.sub',viewer::text,true);
 PERFORM assert_false(public.notification_center_allowed(legacy,viewer),'old hidden-recipient notifications are denied');
 PERFORM assert_false(public.notification_center_in_center_internal(legacy,now()),'old hidden-recipient notifications cannot affect badges or counts');
 result:=public.notification_center_dto(legacy,delivery);
 PERFORM assert_true(result IS NULL,'DTO itself cannot serialize hidden personal notification');
 INSERT INTO public.events(occasion,title,start_time,end_time) VALUES(oc,'Workshop',now(),now()+interval '1 hour') RETURNING id INTO ev;
 INSERT INTO public.event_users(event,"user") VALUES(ev,hidden_user),(ev,viewer);
 result:=public.get_event_participants_for_edit(ev);
 PERFORM assert_eq(jsonb_array_length(result->'data'),1,'program participant list excludes hidden admin');
 result:=public.get_user_info_for_users(ARRAY[hidden_user,viewer],oc);
 PERFORM assert_eq(jsonb_array_length(result->'data'),1,'direct contact hydration excludes hidden admin');
 result:=public.get_last_sign_in_at_for_users(ARRAY[hidden_user,viewer],oc);
 PERFORM assert_eq(jsonb_array_length(result->'data'),1,'login activity hydration excludes hidden admin');
 result:=public.get_occasion_users_for_editor(oc);
 PERFORM assert_eq(jsonb_array_length(result#>'{data,occasion_users}'),1,'alternate editor directory excludes hidden admin');
 INSERT INTO public.user_group_info(occasion,title) VALUES(oc,'Group') RETURNING id INTO grp;
 INSERT INTO public.user_groups("group","user",is_admin) VALUES(grp,viewer,true),(grp,hidden_user,false);
 result:=public.get_user_group_info_with_users(grp);
 PERFORM assert_eq(jsonb_array_length(result->'user_groups'),1,'group member read excludes hidden admin');
 result:=public.get_all_user_groups(oc);
 PERFORM assert_eq(jsonb_array_length(result#>'{groups,0,user_groups}'),1,'all-group listing excludes hidden admin');
 result:=public.get_user_group_command_data_v1(grp);
 PERFORM assert_eq(jsonb_array_length(result->'participants'),1,'group editor and mutation payload exclude hidden admin');
 result:=public.get_private_profile_payload_v1(oc,viewer);
 PERFORM assert_eq(jsonb_array_length(result#>'{groups,0,participants}'),1,'private profile group preview excludes hidden admin');
 result:=public.save_user_group_client_sync_v1(oc,gen_random_uuid(),0,jsonb_build_object('id',grp,'title','Renamed','participants',jsonb_build_array(jsonb_build_object('user_id',viewer,'is_admin',true))));
 PERFORM assert_eq(result->>'status','applied','filtered group edit really applies');
 PERFORM assert_eq(jsonb_array_length(result#>'{data,group,participants}'),1,'save response contains only visible members');
 PERFORM assert_true(EXISTS(SELECT 1 FROM public.user_groups WHERE "group"=grp AND "user"=hidden_user),'saving a filtered group preserves hidden membership');
 result:=public.save_user_group_client_sync_v1(oc,gen_random_uuid(),1,jsonb_build_object('id',grp,'title','Renamed','participants',jsonb_build_array(jsonb_build_object('user_id',viewer,'is_admin',true))));
 PERFORM assert_eq(result->>'status','unchanged','hidden membership does not cause repeated save churn');
 INSERT INTO public.event_feedback(event,occasion,"user",rating) VALUES(ev,oc,hidden_user,'happy');
 result:=public.get_event_feedback_for_edit(ev);
 PERFORM assert_true(result#>'{data,items,0,user_name}'='null'::jsonb,'feedback does not reveal hidden author name');
 PERFORM assert_true((result#>>'{data,items,0,is_anonymous}')::boolean,'hidden feedback appears anonymous');
 result:=public.get_event_feedback_export_for_edit(oc);
 PERFORM assert_true(result#>'{data,0,user_name}'='null'::jsonb,'feedback export does not reveal hidden author name');
 PERFORM set_config('request.jwt.claim.sub',hidden_user::text,true);
 result:=public.get_private_profile_payload_v1(oc,hidden_user);
 PERFORM assert_eq(result#>>'{user,id}',hidden_user::text,'hidden account retains its own profile');
END $$;
ROLLBACK;
